SELECT o.*,
CONCAT(IFNULL(m.company_name,'未知场馆'),
IF(v.code IS NOT NULL, CONCAT(' ', v.code), '')
) AS venue_name
FROM `order` o
LEFT JOIN venue v ON o.venue_id = v.vid
LEFT JOIN merchant m ON v.owner_id = m.mid
WHERE o.user_id = #{uid}

    AND o.status = #{status}

ORDER BY o.create_time DESC

SELECT o.*,
CONCAT(IFNULL(m.company_name,'未知场馆'),
IF(v.code IS NOT NULL, CONCAT(' ', v.code), '')
) AS venue_name
FROM `order` o
LEFT JOIN venue v ON o.venue_id = v.vid
LEFT JOIN merchant m ON v.owner_id = m.mid
WHERE o.venue_id IN (
SELECT vid FROM venue WHERE owner_id = #{merchantId}
)

    AND o.status = #{status}

ORDER BY o.create_time DESC
